MAP
NAME "earthquakes"
STATUS ON
SIZE 1000 800
SYMBOLSET "../etc/symbols.txt"
EXTENT -180 -90 180 90
UNITS DD
SHAPEPATH "../data"
IMAGECOLOR 255 255 255
FONTSET "../etc/fonts.txt"

WEB
  IMAGEPATH "/ms4w/tmp/ms_tmp/" 
  IMAGEURL "/ms_tmp/"
END

PROJECTION
  "init=epsg:4326"
END

#
# Start of layer definitions
#

LAYER
  NAME 'global-raster'
  TYPE RASTER
  DATA "./GLOBALeb3colshade.jpg"
  STATUS DEFAULT
    CLASS
    NAME 'Earth Image' 
  END
  PROJECTION
    "init=epsg:4326"
  END  
END

LAYER
  NAME "earthquakes"
  TYPE POINT
  STATUS ON
  CONNECTIONTYPE OGR
  CONNECTION "earthquakes.db"
  DATA "grid.earthquakes"
  CLASSITEM "mag"
  PROJECTION
    "init=epsg:4326"
  END
  CLASS
    NAME "Earthquakes-class1"
    EXPRESSION ([mag] <= 2)
    STYLE
      SYMBOL "circle"
      SIZE 8
      COLOR 255 165 0
      OUTLINECOLOR 0 0 0
    END
  END
  CLASS
    NAME "Earthquakes-class2"
    EXPRESSION ([mag] <= 4 and [mag] > 2)
    STYLE
      SYMBOL "circle"
      SIZE 14
      COLOR 255 165 0
      OUTLINECOLOR 0 0 0
    END
  END  
  CLASS
    NAME "Earthquakes-class3"
    EXPRESSION ([mag] <= 6 and [mag] > 4)
    STYLE
      SYMBOL "circle"
      SIZE 18
      COLOR 255 140 0
      OUTLINECOLOR 0 0 0
    END
  END  
  CLASS
    NAME "Earthquakes-class4"
    EXPRESSION ([mag] > 6)
    STYLE
      SYMBOL "circle"
      SIZE 26
      COLOR 255 0 0
      OUTLINECOLOR 0 0 0
    END
  END   
END # layer



END # Map File
